describe('<md-gb-select> anchored overlay contract (AnchoredOverlayController: popover, below, flip, light dismiss, focus return)', () => {
  afterEach(() => container?.remove());

  it('opens as a popover in the top layer, below its invoker, start-aligned', async () => {
    // spec: menus-6fe29e, menus-c16cb5, menus-047bed, menus-0cd562
    const f = await setupAnchored0();
    f.anchor.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    expect(f.surface.hasAttribute('popover')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.top).toBeGreaterThanOrEqual(a.bottom - 0.5);
    expect(Math.abs(s.top - a.bottom - 0)).toBeLessThan(1.5);
    expect(Math.abs(s.left - a.left)).toBeLessThan(1.5);
  });

  it('flips to the above when there is no room below', async () => {
    // spec: menus-74a090, menus-876f3e
    const f = await setupAnchored0({edge: 'bottom'});
    f.anchor.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.bottom).toBeLessThanOrEqual(a.top + 0.5);
    expect(Math.abs(a.top - s.bottom - 0)).toBeLessThan(1.5);
    expect(s.top).toBeGreaterThanOrEqual(-0.5);
    expect(s.bottom).toBeLessThanOrEqual(window.innerHeight + 0.5);
  });

  it('stays inside the window at its inline end', async () => {
    // spec: menus-09c5d3, menus-74a090
    const f = await setupAnchored0({edge: 'end'});
    f.anchor.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const s = f.surface.getBoundingClientRect();
    expect(s.left).toBeGreaterThanOrEqual(-0.5);
    expect(s.right).toBeLessThanOrEqual(document.documentElement.clientWidth + 0.5);
  });

  it('closes with Escape', async () => {
    // spec: menus-235f42, menus-8ed4c3
    const f = await setupAnchored0();
    f.anchor.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('closes with a press outside', async () => {
    // spec: menus-509021
    const f = await setupAnchored0();
    f.anchor.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await sendMouse({type: 'click', position: [document.documentElement.clientWidth - 6, 6]});
    await settle();
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('returns focus to the invoker when it was inside', async () => {
    // spec: menus-e50135
    const f = await setupAnchored0();
    f.root.querySelector<HTMLElement>('md-gb-select')!.focus();
  await press('ArrowDown');
    await settle();
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
    expect(deepActive()).toBe(f.invoker);
  });
});

